CREATE OR REPLACE VIEW catalog_exceptions AS SELECT source,product_id,variant_id,title,variant_title,source_url,'source_sku_not_published' AS issue FROM variants WHERE nullif(trim(source_sku),'') IS NULL UNION ALL SELECT source,product_id,variant_id,title,variant_title,source_url,'source_says_unavailable' FROM variants WHERE source_available=false;
CREATE OR REPLACE TABLE sample_shipments(shipment_id VARCHAR,ship_date DATE,origin VARCHAR,destination VARCHAR); INSERT INTO sample_shipments VALUES ('DEMO-1001','2026-10-01','Dallas, TX','Tulsa, OK'),('DEMO-1002','2026-10-02','Fort Worth, TX','Austin, TX'),('DEMO-1003','2026-10-03','Dallas, TX','Houston, TX');
CREATE OR REPLACE TABLE sample_documents(file_name VARCHAR,shipment_id VARCHAR,document_type VARCHAR,date_text VARCHAR,body_id VARCHAR); INSERT INTO sample_documents VALUES ('IMG_4821.jpg','DEMO-1001','cargo-photo','2026-10-01','fixture-body-A'),('IMG_4821-copy.jpg','DEMO-1001','cargo-photo','2026-10-01','fixture-body-A'),('scan_001.pdf','DEMO-1001','delivery-proof','2026-10-01','fixture-body-B'),('SCAN002.pdf','DEMO-1002','shipping-label','2026-10-02','fixture-body-C'),('phone_294.jpg','DEMO-1002','cargo-photo','2026-10-02','fixture-body-D'),('unknown.pdf','DEMO-9999','delivery-proof','2026-10-03','fixture-body-E'),('label_unclear.pdf','DEMO-1003','shipping-label','not-readable','fixture-body-F'),('IMG_992.jpg','DEMO-1003','cargo-photo','2026-10-03','fixture-body-G');
CREATE OR REPLACE VIEW archive_preview AS SELECT d.*,s.origin,s.destination,CASE WHEN s.shipment_id IS NULL THEN 'unmatched_shipment' WHEN try_cast(date_text AS DATE) IS NULL THEN 'date_needs_review' WHEN row_number() OVER(PARTITION BY body_id ORDER BY file_name)>1 THEN 'duplicate_content' ELSE 'ready' END AS disposition,CASE WHEN s.shipment_id IS NOT NULL AND try_cast(date_text AS DATE) IS NOT NULL THEN d.shipment_id||'_'||date_text||'_'||document_type||'_'||substr(sha256(file_name),1,8)||'.'||regexp_extract(file_name,'[.]([^.]+)$',1) END AS proposed_name FROM sample_documents d LEFT JOIN sample_shipments s USING(shipment_id);
CREATE OR REPLACE VIEW missing_delivery_proof AS SELECT s.shipment_id,s.ship_date,s.destination,'No delivery-proof document in this input batch' AS issue FROM sample_shipments s WHERE NOT EXISTS(SELECT 1 FROM sample_documents d WHERE d.shipment_id=s.shipment_id AND d.document_type='delivery-proof');
