COPY (SELECT * FROM catalog_exceptions ORDER BY source,issue,product_id,variant_id) TO '/Users/nickgonzales/Developer/Bonfyre/packs/aurekai-work-samples/site/assets/catalog-exceptions.csv' (HEADER,DELIMITER ',');
COPY (SELECT * FROM archive_preview ORDER BY shipment_id,file_name) TO '/Users/nickgonzales/Developer/Bonfyre/packs/aurekai-work-samples/site/assets/archive-rename-preview.csv' (HEADER,DELIMITER ',');
COPY (SELECT * FROM missing_delivery_proof) TO '/Users/nickgonzales/Developer/Bonfyre/packs/aurekai-work-samples/site/assets/archive-missing-documents.csv' (HEADER,DELIMITER ',');
COPY (SELECT * FROM sample_documents) TO '/Users/nickgonzales/Developer/Bonfyre/packs/aurekai-work-samples/site/assets/archive-input.csv' (HEADER,DELIMITER ',');
SELECT 'archive_rows' AS measure,count(*) AS value FROM archive_preview UNION ALL SELECT disposition,count(*) FROM archive_preview GROUP BY disposition UNION ALL SELECT 'missing_delivery_proof',count(*) FROM missing_delivery_proof;